//! Shared helpers for the #33 visible-text adapter acceptance tests.
//!
//! * Media is **synthetic**: a red/green/blue clip generated by ffmpeg, with the slide text
//!   `RED SLIDE`, `GREEN SLIDE`, `BLUE SLIDE` drawn on each scene when ffmpeg's `drawtext`
//!   works (otherwise solid scenes; the tests do not depend on the drawn pixels).
//! * **No OCR model runs.** The OCR backend is visual-analysis' real
//!   `JsonCommandOcrBackend` pointed at a scripted command written here: it reads the first
//!   pixel of each sampled frame PNG (the scene's background colour) and prints a fixed
//!   `OcrDocument` with that scene's slide text. Frame sampling, OCR orchestration and text
//!   tracking are the real upstream code paths.

#![allow(dead_code)]

use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use media_intelligence_analysis::visible_text::{
    OcrBackendConfig, OcrLocalModelOptions, VisualAnalysisOcrConfig,
};

use crate::common::{file_hash, Clip};

/// Model id of the scripted backend in receipts.
pub const SCRIPTED_OCR_NAME: &str = "acceptance-scripted-ocr";
/// Declared model version of the scripted backend.
pub const SCRIPTED_OCR_VERSION: &str = "script-1";

/// Scene colour, slide text and duration (s) of the slide clip: scenes [0,5), [5,12),
/// [12,16) at 25 fps, as for the #27 three-scene clip.
pub const SLIDES: [(&str, &str, u32); 3] = [
    ("red", "RED SLIDE", 5),
    ("green", "GREEN SLIDE", 7),
    ("blue", "BLUE SLIDE", 4),
];

fn tools_available(test: &str) -> bool {
    let runs = |program: &str, arg: &str| {
        Command::new(program)
            .arg(arg)
            .output()
            .map(|output| output.status.success())
            .unwrap_or(false)
    };
    if !runs("ffmpeg", "-version") || !runs("ffprobe", "-version") {
        eprintln!(
            "SKIPPED {test}: ffmpeg/ffprobe not found on PATH; this test needs them to \
             generate synthetic media and to run the real visual-analysis producers"
        );
        return false;
    }
    if !runs("python3", "--version") {
        eprintln!("SKIPPED {test}: python3 not found on PATH; the scripted OCR command needs it");
        return false;
    }
    true
}

fn encode(path: &Path, with_text: bool) -> bool {
    let mut command = Command::new("ffmpeg");
    command.args(["-hide_banner", "-loglevel", "error", "-y"]);
    for (colour, text, seconds) in SLIDES {
        let mut source = format!("color=c={colour}:s=320x240:r=25:d={seconds}");
        if with_text {
            source.push_str(&format!(
                ",drawtext=text='{text}':fontcolor=white:fontsize=28:\
                 x=(w-text_w)/2:y=(h-text_h)/2"
            ));
        }
        command.args(["-f", "lavfi", "-i", &source]);
    }
    command.args([
        "-filter_complex",
        "[0:v][1:v][2:v]concat=n=3:v=1:a=0[v]",
        "-map",
        "[v]",
        "-c:v",
        "libx264",
        "-threads",
        "1",
        "-pix_fmt",
        "yuv420p",
        "-bitexact",
        "-fflags",
        "+bitexact",
    ]);
    command.arg(path);
    command.status().map(|s| s.success()).unwrap_or(false)
}

/// Red/green/blue slide clip (16 s, 25 fps). `None` (after an explicit skip message) when
/// ffmpeg, ffprobe or python3 is missing.
pub fn slides_clip(test: &str) -> Option<Clip> {
    if !tools_available(test) {
        return None;
    }
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("slides.mp4");
    if !encode(&path, true) {
        eprintln!("NOTE {test}: ffmpeg drawtext unavailable; using solid-colour scenes");
        assert!(encode(&path, false), "ffmpeg failed to generate the clip");
    }
    let content_hash = file_hash(&path);
    Some(Clip {
        dir,
        path,
        content_hash,
    })
}

const SCRIPT: &str = r#"#!/usr/bin/env python3
# Acceptance OCR stand-in (#33). NOT an OCR model: it reads the first pixel of the frame
# PNG (the scene background) and prints a fixed OcrDocument for that colour.
import json, struct, sys, zlib

log_path, image_path = sys.argv[1], sys.argv[-1]
with open(log_path, "a") as log:
    log.write(image_path + "\n")

data = open(image_path, "rb").read()
pos, idat, header = 8, b"", None
while pos < len(data):
    length, kind = struct.unpack(">I4s", data[pos:pos + 8])
    body = data[pos + 8:pos + 8 + length]
    if kind == b"IHDR":
        header = struct.unpack(">IIBBBBB", body)
    elif kind == b"IDAT":
        idat += body
    pos += 12 + length
raw = zlib.decompress(idat)
colour_type = header[3]
# Byte 0 is the filter type; for the first pixel of the first row every PNG filter
# leaves the raw value unchanged.
if colour_type in (2, 6):
    r, g, b = raw[1], raw[2], raw[3]
else:
    r = g = b = raw[1]
texts = {0: "RED SLIDE", 1: "GREEN SLIDE", 2: "BLUE SLIDE"}
channels = [r, g, b]
text = texts[channels.index(max(channels))] if max(channels) - min(channels) > 64 else ""
print(json.dumps({
    "text": text,
    "language": "en",
    "confidence": 90,
    "blocks": [],
    "attributes": {},
}))
"#;

/// Writes the scripted OCR command into `dir`. Returns `(command, call log)`; every
/// invocation appends one line to the call log.
pub fn write_ocr_script(dir: &Path) -> (PathBuf, PathBuf) {
    let script = dir.join("scripted-ocr.py");
    fs::write(&script, SCRIPT).unwrap();
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&script, fs::Permissions::from_mode(0o755)).unwrap();
    }
    (script, dir.join("ocr-calls.log"))
}

/// Number of times the scripted command ran.
pub fn script_calls(log: &Path) -> usize {
    fs::read_to_string(log)
        .map(|content| content.lines().count())
        .unwrap_or(0)
}

/// JSON-command backend over the scripted OCR command.
pub fn scripted_config(script: &Path, log: &Path) -> VisualAnalysisOcrConfig {
    let mut config = VisualAnalysisOcrConfig::new(OcrBackendConfig::JsonCommand {
        name: SCRIPTED_OCR_NAME.to_string(),
        command: script.to_path_buf(),
        args: vec![log.display().to_string(), "{image}".to_string()],
    });
    config.model_version = Some(SCRIPTED_OCR_VERSION.to_string());
    config
}

/// ONNX TrOCR backend over a local bundle root; never downloads.
pub fn onnx_config(bundle_root: &Path) -> VisualAnalysisOcrConfig {
    VisualAnalysisOcrConfig::new(OcrBackendConfig::OnnxTrOcr(OcrLocalModelOptions {
        bundle_root: bundle_root.to_path_buf(),
        ..OcrLocalModelOptions::default()
    }))
}
